 function relationshipPanel(){return '<section class="panel relationship" id="relationship"><div class="row between"><h2>Единая история</h2><button data-relationship-refresh>Обновить историю</button></div><p class="hint">События контакта и связанных рабочих карточек. Событие проекта само по себе не означает разговор с человеком.</p><div id="identity-review"></div><div id="subscription-state"></div><div id="relationship-filters"></div><p id="relationship-status" role="status" aria-live="polite"></p><div id="relationship-items"></div><div id="relationship-pages" class="pages"></div><div id="relationship-load" class="actions"></div></section>';}
 const relationshipActive=v=>v&&state.relationship===v&&state.token===v.token&&state.type==='contacts'&&state.entity?.id===v.id&&!!$('#relationship');
 function relationshipFilters(v){const f=v.filters;$('#relationship-filters').innerHTML='<form id="history-filters" class="toolbar"><label>Источник<select name="source">'+options(historySources,f.source||'all')+'</select></label><label>Тип события<select name="kind">'+options(historyKinds,f.kind||'all')+'</select></label><button>Показать</button><details class="extra-filters" '+(f.fromDate||f.toDate?'open':'')+'><summary>Период по Москве</summary><div class="filter-fields"><label>С даты<input class="ym-disable-keys" type="date" name="fromDate" value="'+esc(f.fromDate)+'"></label><label>По дату включительно<input class="ym-disable-keys" type="date" name="toDate" value="'+esc(f.toDate)+'"></label></div></details></form>';$('#history-filters').onsubmit=e=>{e.preventDefault();const filters=Object.fromEntries(new FormData(e.currentTarget)),scan=v.externalStarted;guarded(async()=>{await startRelationship(v.id,filters);if(scan&&relationshipActive(state.relationship))await scanRelationship(state.relationship,false);});};}
