 function activityPanel(){return '<section class="panel viewer-activity" id="viewer-activity"><div class="row between"><h2>Билеты и возвраты</h2>'+(state.activityEnabled?'<button data-activity-refresh>Загрузить историю</button>':'')+'</div><p class="hint">'+(state.activityEnabled?'Сопоставление по email контакта. Проверка запускается по кнопке и не меняет заказы.':'Подключение истории пока выключено. В новой функции CRM нужно включить CRM_ACTIVITY_ENABLED.')+'</p><p id="activity-status" role="status" aria-live="polite"></p><div id="activity-summary"></div><div id="activity-items"></div><button data-activity-more hidden>Проверить следующие записи</button><p class="hint">Погашение билетов показывает работу контроля входа: покупатель мог брать билеты для нескольких человек. Для онлайн-заказа оно не подтверждает просмотр трансляции.</p></section>';}
