async function saveTaskDraft(d){
 const form=$('#task-draft'),err=$('#td-error'),btn=form&&form.querySelector('[type=submit]');if(!form)return;err.textContent='';
 if(!d.ownerId){err.textContent='Выберите ответственного.';return;}
 if(d.contactId===undefined){err.textContent='Выберите контакт или «Без связи с контактом».';return;}
 d.rid=d.rid||rid();btn.disabled=true;let r;
 try{r=await api({action:'task_from_source',sourceRef:d.sourceRef,again:d.again===true,...(d.again?{seen:d.seen}:{}),buyer:taskBuyer(d),request_id:d.rid,data:{title:d.title,description:d.description,ownerId:d.ownerId,contactId:d.contactId||null,status:'open',priority:'normal'}});}
 catch(e){if(state.taskDraft!==d)return;btn.disabled=false;if(e.code){d.rid=null;err.textContent=e.message;return;}
  err.innerHTML=esc('Ответ CRM не дошёл — неизвестно, сохранилась ли задача. Черновик на месте.')+' <button type="button" data-task-check>Проверить</button>';return;}
 if(state.taskDraft!==d)return;
 if(r.created===false){d.checked=true;d.rid=null;d.again=false;d.seen=r.seen;return taskExisting(d,{items:r.existing||[],hidden:r.hidden||0});}
 state.taskDraft=null;openDialog('Задача создана','<p>Задача «'+esc(d.title)+'» создана'+(r.replayed?' (повтор запроса — вторая не создана)':'')+'.</p><div class="actions"><button class="primary" data-task-open="'+esc(r.id)+'">Открыть задачу</button></div>');
}
function taskDraftBar(){$('#task-draft-bar')?.remove();if(!state.taskDraft||!$('#view'))return;const b=document.createElement('div');b.id='task-draft-bar';b.className='task-draft-bar';b.setAttribute('role','status');b.innerHTML='Черновик задачи из заказа не сохранён. <button type="button" data-task-back>Вернуться к черновику</button> <button type="button" data-task-drop>Удалить черновик</button>';b.addEventListener('click',e=>{if(e.target.closest('[data-task-back]')){b.remove();guarded(()=>showTaskDraft(state.taskDraft&&state.taskDraft.again));}if(e.target.closest('[data-task-drop]')){state.taskDraft=null;b.remove();notice('Черновик удалён, в CRM ничего не изменилось.');}});$('#view').before(b);}
