 async function startSegment(){const v=state.segmentView;if(!segmentActive(v)||v.busy)return;v.busy=true;v.error='';v.run=null;v.request=rid();$('#segment-handoff').innerHTML='';$('#segment-results').innerHTML='';const target=$('#segment-target-draft').value,d=v.drafts.find(x=>x.id===target);segmentRunRender(v);try{const r=await api({action:'segment_start',segmentId:v.id,targetDraftId:d?.id,targetDraftRevision:d?.revision,request_id:v.request});if(!segmentActive(v))return;v.run=r.run;v.busy=false;await continueSegment(v);}catch(err){if(segmentActive(v)){v.busy=false;v.error=err.message;segmentRunRender(v);}}}
