 function indexActive(v){return v&&state.indexView===v&&state.token===v.token&&state.tab==='management'&&isOwner()&&!!$('#source-index-panel');}
 async function indexOpen(){
  clearTimeout(state.indexTimer);const v={token:state.token,generation:0,busy:false,data:null,error:''};state.indexView=v;
  if(!state.indexEnabled){$('#source-index-panel').innerHTML='<h2>Обновление источников</h2><p class="hint">Для фонового индекса нужны функция CRM R11, CRM_INDEX_ENABLED=1 и закрытый обработчик по инструкции внедрения.</p>';return;}
  await indexCheck(v);
 }
 function indexRender(v){
  if(!indexActive(v))return;clearTimeout(state.indexTimer);const r=v.data,j=r?.job;
  const phase={scan:'Обновляем записи',verify:'Проверяем состав источников',publish:'Готовим новую версию'};
  const groups={orders:'Заказы',refunds:'Возвраты',leads:'Заявки',campaigns1:'Архивные рассылки',campaigns2:'Рассылки',deliveries:'Журнал отправок',subscribers:'Подписчики',controls:'Состояния кампаний'};
  const status=j?.status==='running'?(phase[j.phase]||'Обновление')+(j.group?' · '+(groups[j.group]||'Источники'):''):r?.queued?'Запрос обновления в очереди':r?.ready?r.stale?'Данные устарели':'Готовый индекс доступен':'Первый индекс ещё не готов';
  $('#source-index-panel').innerHTML='<h2>Обновление источников</h2><p class="'+(r?.stale||r?.issue?'bad':'hint')+'" role="status">'+esc(v.error||status)+'</p>'+
   (r?.sourceIndex?'<p class="index-meta">Обход источников: '+esc(date(r.sourceIndex.startedAt))+' — '+esc(date(r.sourceIndex.completedAt))+' · МСК.</p>':'')+
   (j?'<p class="hint">Обработано: '+j.processed+' · из готового индекса: '+j.reused+' · прочитано заново: '+j.read+' · удалено: '+(j.removed||0)+' · проверено: '+j.verified+'</p>':'')+
   (r?.lastTickAt?'<p class="hint">Последний запуск фона: '+esc(date(r.lastTickAt))+' · МСК.</p>':'<p class="hint">Фоновый обработчик ещё не отмечал запуск. Проверьте его подключение по инструкции внедрения.</p>')+
   (r?.issue?'<p class="bad">'+esc(r.issue.message)+'</p>':'')+
   '<div class="actions"><button data-index-refresh '+(v.busy?'disabled':'')+'>Запросить обновление</button><button data-index-check '+(v.busy?'disabled':'')+'>Проверить состояние</button></div><details class="index-extra"><summary>Полное перестроение</summary><p class="hint">Заново прочитать исходные записи вместо переиспользования готовых данных. Подходит после исправления повреждённого индекса или изменения настроек. Это дольше обычного обновления.</p><button data-index-rebuild '+(v.busy?'disabled':'')+'>Перестроить полностью</button></details><p class="hint">Обновление продолжится при закрытой странице. Новый индекс станет доступен целиком после проверки; время его актуальности видно в отчёте. Данные заказов и подписчиков этим действием не меняются.</p>';
  if(!v.busy&&(r?.queued||j?.status==='running'))state.indexTimer=setTimeout(()=>{if(indexActive(v))indexCheck(v);},15000);
 }
 async function indexCheck(v=state.indexView){
  if(!indexActive(v)||v.busy)return;const generation=++v.generation;v.busy=true;v.error='';
  if(!v.data)$('#source-index-panel').innerHTML='<h2>Обновление источников</h2><p class="hint" role="status">Проверяем состояние…</p>';else indexRender(v);
  try{const r=await api({action:'index_status'});if(!indexActive(v)||v.generation!==generation)return;v.data=r;}catch(err){if(indexActive(v)&&v.generation===generation)v.error=err.message;}
  finally{if(indexActive(v)&&v.generation===generation){v.busy=false;indexRender(v);}}
 }
 async function indexRefresh(force=false){
  const v=state.indexView;if(!indexActive(v)||v.busy)return;const generation=++v.generation;v.busy=true;v.error='';indexRender(v);
  const request=v.request&&v.request.force===force?v.request:(v.request={id:rid(),force});
  try{const r=await api({action:'index_refresh',force,request_id:request.id});if(!indexActive(v)||v.generation!==generation)return;v.data=r;v.request=null;}catch(err){if(indexActive(v)&&v.generation===generation)v.error=err.message;}
  finally{if(indexActive(v)&&v.generation===generation){v.busy=false;indexRender(v);}}
 }

